{
  "case_id": "C09",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "Hook: two true headlines",
      "narration": "\"Cuts heart attacks and strokes by 42 percent.\" \"Lowers your risk by under two percentage points.\" Both of those headlines come from the same trial, and both are true. Here's how that works.",
      "on_screen": "Two newspaper-style headlines side by side, both stamped TRUE, with an arrow pointing back to a single study icon.",
      "claim_refs": ["SYN-C09:Background", "SYN-C09:Results"]
    },
    {
      "beat": "The trial",
      "narration": "Nearly ten thousand adults aged forty-five to seventy, none with existing heart disease and all at low predicted risk, were randomly given either a statin or a dummy pill. Neither they nor their doctors knew which. Researchers then counted first major cardiovascular events over about four years.",
      "on_screen": "9,842 adults split into two equal groups of 4,921; pill bottles labelled STATIN and PLACEBO; a clock reading 4.1 years.",
      "claim_refs": ["SYN-C09:Abstract", "SYN-C09:Population", "SYN-C09:Methods"]
    },
    {
      "beat": "The raw counts",
      "narration": "In the placebo group, 209 people had an event: about 4.25 percent. On the statin, 121 people did: about 2.46 percent. So the risk fell by 1.79 percentage points.",
      "on_screen": "Two grids of 100 figures. Placebo grid: about 4 highlighted. Statin grid: about 2 highlighted. Caption: 4.25% to 2.46%.",
      "claim_refs": ["SYN-C09:Abstract", "SYN-C09:Results"]
    },
    {
      "beat": "Relative versus absolute",
      "narration": "That 1.79 points is the absolute risk reduction: what one person's own risk actually changed by. The 42 percent is the relative reduction, because 1.79 is 42 percent of 4.25. Same result, different yardstick. Relative sounds bigger, especially when the starting risk is small.",
      "on_screen": "One bar shrinking from 4.25 to 2.46, annotated twice: 'minus 1.79 points (absolute)' and 'minus 42% (relative)'.",
      "claim_refs": ["SYN-C09:Results", "SYN-C09:Background"]
    },
    {
      "beat": "What it means for you",
      "narration": "Put another way: about 56 low-risk people take a statin for four years for one to avoid an event. Whether that's worth it is a conversation with your doctor, and this trial can't tell you about longer-term benefits or harms.",
      "on_screen": "56 figures, one turning green. Caption: NNT = 56 over 4.1 years. Footnote: follow-up 4.1 years; harms reported separately.",
      "claim_refs": ["SYN-C09:Results", "SYN-C09:Limitations", "SYN-C09:Discussion"]
    }
  ]
}
